#include "DesktopPreferences.h"
#include "SymbolPairing.h"
#include <cassert>
#include <iostream>
int main(int argc,char**argv){assert(argc==2);std::filesystem::path file=argv[1];assert(!std::filesystem::exists(file));for(int mode=0;mode<3;++mode)for(int accent=0;accent<4;++accent)for(bool dark:{false,true}){private_input::DesktopTheme theme{mode,accent};auto p=theme.palette(dark);assert(p.text.contrast(p.background)>=4.5);assert(p.text.contrast(p.selection)>=4.5);}auto pair=private_input::symbolPlan(L"(");assert(pair.text==L"()"&&pair.caretBack==1);assert(private_input::symbolPlan(L"(",true,false).caretBack==0);assert(private_input::symbolPlan(L"(",false,true).text==L"(");assert(private_input::symbolPlan(L"'").text==L"'");assert(private_input::symbolPlan(L"text(").text==L"text(");{std::ofstream out(file);out<<"{\"themeMode\":\"dark\",\"themeAccent\":\"violet\",\"pairSymbols\":false,\"caretInside\":false}";}auto p=readDesktopInputPreferences(file);assert(p.theme.mode==2&&p.theme.accent==2&&!p.pairSymbols&&!p.caretInside);std::filesystem::remove(file);std::cout<<"desktop theme: 24 readable palettes, four accents, system/light/dark, independent symbol pair/caret settings passed\n";}
